class RemoteRow(dict):
    def __getattr__(self, name):
        return self[name]

class RemoteResult:
    def __init__(self, rows=None):
        self.rows = rows or []
    def fetchone(self):
        return self.rows[0] if self.rows else None
    def fetchall(self):
        return self.rows

class SupabaseDB:
    def __init__(self):
        import requests
        self.requests = requests
        self.base = SUPABASE_URL.rstrip('/') + '/rest/v1/'
        self.headers = {
            'apikey': SUPABASE_KEY,
            'Authorization': 'Bearer ' + SUPABASE_KEY,
            'Content-Type': 'application/json',
            'Accept': 'application/json'
        }
    def _url(self, table):
        return self.base + table
    def _get(self, table, params=None):
        raw=params or {}
        fixed=[]

        for k,v in raw.items():
            if k.startswith("gte."):
                fixed.append((k[4:],"gte."+str(v)))
            elif k.startswith("lte."):
                fixed.append((k[4:],"lte."+str(v)))
            elif k.startswith("gt."):
                fixed.append((k[3:],"gt."+str(v)))
            elif k.startswith("lt."):
                fixed.append((k[3:],"lt."+str(v)))
            elif k.startswith("neq."):
                fixed.append((k[4:],"neq."+str(v)))
            else:
                fixed.append((k,v))

        r=self.requests.get(
            self._url(table),
            headers=self.headers,
            params=fixed,
            timeout=20
        )

        if not r.ok:
            raise RuntimeError(f"Supabase GET {r.status_code}: {r.text[:300]}")

        return r.json()
    def _post(self, table, payload):
        h=dict(self.headers); h['Prefer']='return=representation'
        r=self.requests.post(self._url(table), headers=h, json=payload, timeout=20)
        if r.status_code in (409, 422):
            raise sqlite3.IntegrityError(r.text)
        if not r.ok:
            raise RuntimeError(f"Supabase POST {r.status_code}: {r.text[:300]}")
        return r.json()
    def _patch(self, table, filters, payload):
        h=dict(self.headers); h['Prefer']='return=representation'
        r=self.requests.patch(self._url(table), headers=h, params=filters, json=payload, timeout=20)
        if r.status_code in (409,422):
            raise sqlite3.IntegrityError(r.text)
        if not r.ok:
            raise RuntimeError(f"Supabase PATCH {r.status_code}: {r.text[:300]}")
        return r.json()
    def _upload_storage(self, bucket, path, data, content_type):
        url = SUPABASE_URL.rstrip('/') + f'/storage/v1/object/{bucket}/{path}'
        h = {
            'apikey': SUPABASE_KEY,
            'Authorization': 'Bearer ' + SUPABASE_KEY,
            'Content-Type': content_type,
            'Content-Length': str(len(data)),
            'Cache-Control': '3600'
        }

        last_error = None
        for attempt in range(3):
            try:
                r = self.requests.post(
                    url,
                    headers=h,
                    data=data,
                    timeout=(15, 60)
                )
                if r.ok:
                    return SUPABASE_URL.rstrip('/') + f'/storage/v1/object/public/{bucket}/{path}'

                last_error = f"Supabase Storage POST {r.status_code}: {r.text[:300]}"

            except Exception as e:
                last_error = f"{type(e).__name__}: {e}"

        raise RuntimeError(f"Gagal upload foto setelah 3 percobaan: {last_error}")

    def _delete(self, table, filters):
        r=self.requests.delete(self._url(table), headers=self.headers, params=filters, timeout=20)
        if not r.ok:
            raise RuntimeError(f"Supabase DELETE {r.status_code}: {r.text[:300]}")
        return r.json() if r.text else []
    def execute(self, sql, params=()):
        q=' '.join(sql.strip().split())
        u=q.upper()
        # INSERT
        if u.startswith('INSERT INTO SISWA'):
            vals=dict(zip(['nis','nama','kelas','qr','orang_tua','whatsapp','hubungan','foto'], params))
            return RemoteResult([RemoteRow(x) for x in self._post('siswa', vals)])
        if u.startswith('INSERT INTO NILAI_AKADEMIK'):
            fields=['nis','nama','kelas','mata_pelajaran','tugas','ulangan','pts','pas','nilai_akhir','predikat','semester','tahun_ajaran']
            vals=dict(zip(fields, params))
            return RemoteResult([RemoteRow(x) for x in self._post('nilai_akademik', vals)])

        if u.startswith('INSERT INTO TENAGA'):
            vals=dict(zip(['nip','nama','jabatan','qr','foto'], params))
            return RemoteResult([RemoteRow(x) for x in self._post('tenaga', vals)])
        if u.startswith('INSERT INTO ABSENSI_TENAGA'):
            vals=dict(zip(['nip','nama','jabatan','tanggal','jam','status'], params))
            return RemoteResult([RemoteRow(x) for x in self._post('absensi_tenaga', vals)])
        if u.startswith('INSERT INTO ABSENSI'):
            vals=dict(zip(['nis','nama','kelas','tanggal','jam','status'], params))
            return RemoteResult([RemoteRow(x) for x in self._post('absensi', vals)])
        if u.startswith('INSERT INTO USERS'):
            vals = list(params)

            # Akun biasa: username, password, role
            # Akun orang tua: username, password, role, nis
            if len(vals) >= 4:
                fields = ['username', 'password', 'role', 'nis']
            else:
                fields = ['username', 'password', 'role']

            payload = dict(zip(fields, vals))
            return RemoteResult([RemoteRow(x) for x in self._post('users', payload)])
        # UPDATE
        if u.startswith('UPDATE SISWA SET'):
            fields=['nis','nama','kelas','qr','orang_tua','whatsapp','hubungan']; vals=params
            payload=dict(zip(fields, vals[:-1])); sid=vals[-1]
            return RemoteResult([RemoteRow(x) for x in self._patch('siswa', {'id':f'eq.{sid}'}, payload)])
        if u.startswith('UPDATE TENAGA SET'):
            fields=['nip','nama','jabatan','qr']; vals=params
            payload=dict(zip(fields, vals[:-1])); tid=vals[-1]
            return RemoteResult([RemoteRow(x) for x in self._patch('tenaga', {'id':f'eq.{tid}'}, payload)])
        # UPDATE USERS
        if u.startswith('UPDATE USERS SET'):
            vals = list(params)
            user_id = vals[-1]
            payload = {}
            fields = re.findall(r'([A-Z_]+)=\\?', u.split('SET', 1)[1].split('WHERE', 1)[0])

            for i, field in enumerate(fields):
                if i >= len(vals) - 1:
                    break
                payload[field.lower()] = vals[i]

            return RemoteResult([RemoteRow(x) for x in self._patch(
                'users',
                {'id': f'eq.{user_id}'},
                payload
            )])

        # DELETE
        if u.startswith('DELETE FROM SISWA'):
            return RemoteResult([RemoteRow(x) for x in self._delete('siswa', {'id':f'eq.{params[0]}'} )])
        if u.startswith('DELETE FROM TENAGA'):
            return RemoteResult([RemoteRow(x) for x in self._delete('tenaga', {'id':f'eq.{params[0]}'} )])
        # simple users lookup
        if u == 'SELECT USERNAME FROM USERS ORDER BY ID LIMIT 1':
            rows = self._get('users', {'select':'username','order':'id.asc','limit':'1'})
            return RemoteResult([RemoteRow(x) for x in rows])
        # login
        if 'FROM USERS WHERE USERNAME=? AND PASSWORD=?' in u:
            rows=self._get('users', {'select':'*','username':f'eq.{params[0]}','password':f'eq.{params[1]}','limit':'1'})
            return RemoteResult([RemoteRow(x) for x in rows])
        # lookup akun berdasarkan username (dashboard orang tua/profil)
        if 'FROM USERS WHERE USERNAME=?' in u and 'PASSWORD=?' not in u:
            rows=self._get('users', {'select':'*','username':f'eq.{params[0]}','limit':'1'})
            return RemoteResult([RemoteRow(x) for x in rows])

        # COUNT(*) compatibility for dashboard/report queries
        m_count = re.match(r'^SELECT COUNT\(\*\) FROM ([A-Z_]+)(?: WHERE (.*))?$', u)
        if m_count:
            table = m_count.group(1).lower()
            where = m_count.group(2) or ''
            q = {'select':'id','limit':'10000'}

            # Filter tanggal
            if 'TANGGAL BETWEEN ? AND ?' in where and len(params) >= 2:
                q['gte.tanggal'] = params[0]
                q['lte.tanggal'] = params[1]
            elif 'TANGGAL=?' in where and len(params) >= 1:
                q['tanggal'] = f'eq.{params[0]}'

            # Filter kelas
            m_kelas = re.search(r'KELAS=\?', where)
            if m_kelas:
                # Cari parameter kelas berdasarkan posisi parameter
                if 'TANGGAL=?' in where and len(params) >= 2:
                    q['kelas'] = f'eq.{params[1]}'
                elif len(params) >= 1:
                    q['kelas'] = f'eq.{params[-1]}'

            # Filter status literal, misalnya STATUS='Masuk'
            m_status = re.search(r"STATUS=\s*'([^']*)'", where)
            if m_status:
                status_value = m_status.group(1).strip().lower()

                # Query disimpan dalam huruf besar karena normalisasi SQL,
                # sedangkan nilai asli di Supabase menggunakan "Masuk"/"Pulang".
                status_map = {
                    "masuk": "Masuk",
                    "pulang": "Pulang",
                    "hadir": "Hadir",
                    "izin": "Izin",
                    "sakit": "Sakit",
                    "alpa": "Alpa"
                }

                status_value = status_map.get(status_value, m_status.group(1))
                q['status'] = f"eq.{status_value}"

            elif 'STATUS=?' in where:
                # Untuk query status parameterized
                if len(params) >= 2:
                    q['status'] = f'eq.{params[-1]}'
                elif len(params) >= 1:
                    q['status'] = f'eq.{params[0]}'

            rows = self._get(table, q)
            return RemoteResult([(len(rows),)])

        # classes / GROUP BY compatibility
        if 'SELECT KELAS,COUNT(*) TOTAL FROM SISWA GROUP BY KELAS' in u:
            rows=self._get('siswa', {'select':'kelas','order':'kelas.asc','limit':'10000'})
            counts={}
            for x in rows:
                k=(x.get('kelas') or '').strip()
                if k: counts[k]=counts.get(k,0)+1
            return RemoteResult([RemoteRow({'kelas':k,'total':counts[k]}) for k in sorted(counts, key=lambda z:z.lower())])
        if 'SELECT DISTINCT KELAS FROM SISWA' in u:
            rows=self._get('siswa', {'select':'kelas','order':'kelas.asc','limit':'10000'})
            seen=[]
            for x in rows:
                k=(x.get('kelas') or '').strip()
                if 'KELAS<>\'\'' in u and not k: continue
                if k not in seen: seen.append(k)
            return RemoteResult([RemoteRow({'kelas':k}) for k in seen])
        # lookup siswa berdasarkan NIS (dashboard orang tua)
        if 'FROM SISWA WHERE NIS=?' in u:
            rows=self._get('siswa', {'select':'*','nis':f'eq.{params[0]}','limit':'1'})
