@app.route("/edit_nilai_tugas/<int:tugas_id>", methods=["GET", "POST"])
@login_required
def edit_nilai_tugas(tugas_id):
    if session.get("role") not in ("admin", "guru"):
        return redirect(url_for("home"))

    c = db()

    tugas = c.execute(
        "SELECT * FROM nilai_tugas WHERE id=?",
        (tugas_id,)
    ).fetchone()

    if not tugas:
        c.close()
        flash("Data tugas harian tidak ditemukan.")
        return redirect(url_for("nilai_siswa"))

    if session.get("role") == "guru":
        kelas_guru = str(session.get("kelas") or "").strip()
        if kelas_guru and str(tugas["kelas"] or "").strip() != kelas_guru:
            c.close()
            flash("Guru hanya dapat mengedit tugas siswa dari kelasnya sendiri.")
            return redirect(url_for("nilai_siswa"))

    if request.method == "POST":
        tanggal_tugas = (request.form.get("tanggal_tugas") or "").strip()
        nilai = (request.form.get("nilai") or "0").strip()
        keterangan = (request.form.get("keterangan") or "").strip()
        semester = (request.form.get("semester") or "").strip()
        tahun_ajaran = (request.form.get("tahun_ajaran") or "").strip()

        try:
            nilai_num = float(nilai)
        except Exception:
            nilai_num = -1

        if not tanggal_tugas or nilai_num < 0 or nilai_num > 100:
            c.close()
            flash("Tanggal dan nilai harus diisi dengan benar (0-100).")
            return redirect(url_for("edit_nilai_tugas", tugas_id=tugas_id))

        c.execute(
            """UPDATE nilai_tugas
               SET tanggal_tugas=?, nilai=?, keterangan=?, semester=?, tahun_ajaran=?
               WHERE id=?""",
            (
                tanggal_tugas,
                nilai_num,
                keterangan,
                semester,
                tahun_ajaran,
                tugas_id
            )
        )
        c.commit()

        # Sinkronkan rata-rata Tugas Harian setelah diedit
        sync_nilai_tugas(
            tugas["nis"],
            tugas["mata_pelajaran"],
            semester,
            tahun_ajaran
        )

        # Kirim notifikasi setelah tugas harian berhasil diperbarui
        nama_tugas = str(tugas["nama"] or "")
        mapel_tugas = str(tugas["mata_pelajaran"] or "")

        kirim_notifikasi_fcm(
            tugas["nis"],
            f"Nilai Tugas {mapel_tugas}",
            f"{nama_tugas} mendapatkan nilai {nilai_num:g} pada hari ini.",
            {
                "jenis": "nilai_tugas",
                "nis": str(tugas["nis"]),
                "mata_pelajaran": mapel_tugas,
                "route": "/dashboard_orangtua"
            }
        )

        c.close()

        flash("Tugas Harian berhasil diperbarui.")
        return redirect(url_for("nilai_siswa"))

    body = f"""
    <div class="nilai-form-card">
        <h2>Edit Tugas Harian</h2>
        <p><b>{escape(str(tugas["nama"] or "-"))}</b> —
           {escape(str(tugas["mata_pelajaran"] or "-"))}</p>

        <form method="post">
            <label>Tanggal Tugas</label>
            <input type="date" name="tanggal_tugas"
                   value="{escape(str(tugas["tanggal_tugas"] or ""))}" required>

            <label>Nilai</label>
            <input type="number" name="nilai" min="0" max="100"
                   step="0.01"
                   value="{escape(str(tugas["nilai"] or "0"))}" required>

            <label>Keterangan</label>
            <input type="text" name="keterangan"
                   value="{escape(str(tugas["keterangan"] or ""))}">

            <label>Semester</label>
            <select name="semester">
                <option value="1" {"selected" if str(tugas["semester"] or "") == "1" else ""}>Semester 1</option>
                <option value="2" {"selected" if str(tugas["semester"] or "") == "2" else ""}>Semester 2</option>
            </select>

            <label>Tahun Ajaran</label>
            <input type="text" name="tahun_ajaran"
                   value="{escape(str(tugas["tahun_ajaran"] or ""))}">

            <button type="submit">Simpan Perubahan</button>
            <a href="/nilai_siswa">Batal</a>
        </form>
    </div>
    """

    c.close()
    return page("Edit Tugas Harian", body)


@app.route("/nilai_tugas", methods=["POST"])
@login_required
def nilai_tugas():
    if session.get("role") not in ("admin", "guru"):
        return redirect(url_for("home"))

    nis = request.form.get("nis", "").strip()
    mata_pelajaran = request.form.get("mata_pelajaran", "").strip()
    tanggal_tugas = request.form.get("tanggal_tugas", "").strip()
    nilai = request.form.get("nilai", "0").strip() or "0"
    keterangan = request.form.get("keterangan", "").strip()
    semester = request.form.get("semester", "").strip()
    tahun_ajaran = request.form.get("tahun_ajaran", "").strip()

    if not nis or not mata_pelajaran or not tanggal_tugas:
        flash("Siswa, mata pelajaran, dan tanggal tugas wajib diisi.", "warn")
        return redirect(url_for("nilai_siswa"))

    try:
        angka = float(nilai)
        if angka < 0 or angka > 100:
            raise ValueError
    except ValueError:
        flash("Nilai tugas harus berupa angka 0 sampai 100.", "warn")
        return redirect(url_for("nilai_siswa"))

    c = db()
    try:
        siswa_row = c.execute(
            "SELECT * FROM siswa WHERE nis=?",
            (nis,)
        ).fetchone()

        if not siswa_row:
            flash("Siswa tidak ditemukan.", "warn")
            return redirect(url_for("nilai_siswa"))

        if (
            session.get("role") == "guru"
            and str(siswa_row["kelas"] or "").strip()
            != str(session.get("kelas") or "").strip()
        ):
            flash("Guru hanya dapat memasukkan tugas untuk siswa dari kelasnya sendiri.", "warn")
            return redirect(url_for("nilai_siswa"))

        c.execute(
            """INSERT INTO nilai_tugas
            (nis,nama,kelas,mata_pelajaran,tanggal_tugas,nilai,keterangan,semester,tahun_ajaran)
            VALUES(?,?,?,?,?,?,?,?,?)""",
            (
                nis,
                siswa_row["nama"] or "",
                siswa_row["kelas"] or "",
                mata_pelajaran,
                tanggal_tugas,
                angka,
                keterangan,
                semester,
                tahun_ajaran
            )
        )
        c.commit()

        # Kirim notifikasi segera setelah tugas berhasil disimpan.
        # Tidak bergantung pada proses sinkronisasi Nilai Akademik.
        nama_siswa_tugas = str(siswa_row["nama"] or "")

        kirim_notifikasi_fcm(
            nis,
            f"Nilai Tugas {mata_pelajaran}",
            f"{nama_siswa_tugas} mendapatkan nilai {angka:g} pada hari ini.",
            {
                "jenis": "nilai_tugas",
                "nis": str(nis),
                "mata_pelajaran": str(mata_pelajaran),
                "route": "/dashboard_orangtua"
            }
        )

        # Sinkronkan rata-rata Tugas Harian ke Nilai Akademik
        sync_nilai_tugas(
            nis,
            mata_pelajaran,
            semester,
            tahun_ajaran
        )

        flash("Tugas harian berhasil disimpan.", "ok")
    except Exception as e:
        flash(f"Gagal menyimpan tugas harian: {escape(str(e))}", "warn")
    finally:
        c.close()

    return redirect(url_for("nilai_siswa"))





@app.route("/obrolan_admin", methods=["GET"])
@login_required
def obrolan_admin():
    if session.get("role") != "admin":
        return redirect(url_for("home"))

    c = db()

    try:
        siswa_rows = c._get(
            "siswa",
            {
                "select": "nis,nama,kelas",
                "order": "nama.asc",
                "limit": "1000"
            }
        )

        semua_obrolan = c._get(
            "obrolan",
            {
                "select": "*",
                "order": "created_at.desc,id.desc",
                "limit": "2000"
            }
        )

        c.close()

        siswa_map = {
            str(s.get("nis") or "").strip(): s
            for s in siswa_rows
            if s.get("nis")
        }

        # Ambil satu sesi terbaru untuk setiap siswa.
        percakapan = {}

        for row in semua_obrolan:
            nis = str(row.get("nis") or "").strip()

            if not nis:
                continue

            if nis not in percakapan:
                percakapan[nis] = row

        trs = ""

        for nis, row in percakapan.items():
            siswa = siswa_map.get(nis, {})

            nama = escape(str(siswa.get("nama") or "-"))
            kelas = escape(str(siswa.get("kelas") or "-"))

            status = escape(str(row.get("status") or "-"))
            status_sesi = str(row.get("status_sesi") or "aktif").strip()

            pesan = escape(str(row.get("pesan") or ""))
            pesan = pesan.replace("\n", " ")

            diteruskan = bool(row.get("diteruskan"))
            tujuan = escape(str(row.get("diteruskan_ke") or "").strip())

            if status_sesi == "selesai":
                status_tampil = "✅ Chat Selesai"
            elif diteruskan and tujuan:
                status_tampil = f"🔄 {status}"
            else:
                status_tampil = status

            trs += f"""
            <tr>
                <td>
                    <strong>{nama}</strong><br>
                    <small>Kelas {kelas} • NIS: {escape(nis)}</small>
                </td>
                <td>{status_tampil}</td>
                <td>{escape(pesan[:120])}</td>
                <td>
                    <a class="btn" href="/obrolan_admin/{escape(nis)}">
                        <img class="open-chat-icon"
                             src="/static/images/iconbukaobrolan.png"
                             alt=""> Buka
                    </a>
                </td>
            </tr>
            """

        if not trs:
            trs = """
            <tr>
                <td colspan="4"
                    style="text-align:center;padding:25px">
                    Belum ada percakapan dari orang tua.
                </td>
            </tr>
            """

        body = f"""
        <div class="card">
            <h2>
                <img class="menu-chat-icon"
                     src="/static/images/iconobrolanchatt.png"
                     alt="">
                Obrolan Administrator
            </h2>

            <div class="small" style="margin-bottom:12px">
                Kelola percakapan orang tua, alihkan ke Wali Kelas,
                dan lihat riwayat chat yang sudah selesai.
            </div>

            <div style="overflow-x:auto">
                <table>
                    <thead>
                        <tr>
                            <th>Siswa</th>
                            <th>Status</th>
                            <th>Pesan Terakhir</th>
                            <th>Aksi</th>
                        </tr>
                    </thead>
                    <tbody>
                        {trs}
                    </tbody>
                </table>
            </div>
        </div>
        """

        return page("Obrolan Administrator", body)

    except Exception as e:
        try:
            c.close()
        except Exception:
            pass

        return page(
            "Obrolan Administrator",
            f'<div class="card">'
            f'<h2><img class="menu-chat-icon" '
            f'src="/static/images/iconobrolanchatt.png" alt=""> '
            f'Obrolan</h2>'
            f'<div class="warn">Gagal membuka obrolan:<br>'
            f'<small>{escape(str(e))}</small></div></div>'
        )

