def upload_foto_siswa(file):
    if not file or not file.filename:
        return ""
    nama_file = (file.filename.rsplit("/", 1)[-1]).strip()
    ext = nama_file.rsplit(".", 1)[-1].lower() if "." in nama_file else ""
    if ext not in ("jpg", "jpeg", "png", "webp"):
        raise ValueError("Format foto harus JPG, JPEG, PNG, atau WEBP.")
    data = file.read()
    if len(data) > 6 * 1024 * 1024:
        raise ValueError("Ukuran foto maksimal 6 MB.")
    import uuid
    nama_storage = f"siswa/{uuid.uuid4().hex}.{ext}"
    content_type = file.mimetype or "image/jpeg"
    c = db()
    try:
        return c._upload_storage("foto-siswa", nama_storage, data, content_type)
    finally:
        c.close()


@app.route("/buku_induk", methods=["GET"])
@admin_required
def buku_induk():
    kelas = request.args.get("kelas", "").strip()

    c = db()
    try:
        if kelas:
            siswa = c._get("siswa", {
                "select": "*",
                "kelas": f"eq.{kelas}",
                "order": "nama.asc"
            })
        else:
            siswa = c._get("siswa", {
                "select": "*",
                "order": "nama.asc"
            })

        kelas_rows = c._get("siswa", {
            "select": "kelas",
            "order": "kelas.asc"
        })
    finally:
        c.close()

    kelas_list = sorted(set(
        str(x.get("kelas") or "").strip()
        for x in kelas_rows
        if str(x.get("kelas") or "").strip()
    ))

    from datetime import date

    def hitung_umur(tgl):
        if not tgl:
            return "-"
        try:
            lahir = datetime.strptime(str(tgl)[:10], "%Y-%m-%d").date()
            hari_ini = date.today()
            umur = hari_ini.year - lahir.year
            if (hari_ini.month, hari_ini.day) < (lahir.month, lahir.day):
                umur -= 1
            return str(umur) + " tahun"
        except Exception:
            return "-"

    rows_html = ""

    for no, x in enumerate(siswa, 1):
        sid = x.get("id", "")
        nis = escape(str(x.get("nis") or ""))
        nama = escape(str(x.get("nama") or ""))
        kls = escape(str(x.get("kelas") or ""))
        tgl = escape(str(x.get("tanggal_lahir") or ""))
        umur = hitung_umur(x.get("tanggal_lahir"))

        foto = x.get("foto") or ""
        if foto:
            foto_html = f'<img class="buku-foto" src="{escape(foto)}" alt="Foto">'
        else:
            foto_html = '<div class="buku-foto buku-foto-default">👤</div>'

        rows_html += f"""
<tr>
<td>{no}</td>
<td>{foto_html}</td>
<td>{nis}</td>
<td><b>{nama}</b></td>
<td>{kls}</td>
<td>{tgl}</td>
<td>{umur}</td>
<td>
<a class="btn purple" href="/edit_siswa/{sid}">Lihat / Edit</a>
</td>
</tr>
"""

    pilihan_kelas = '<option value="">Semua Kelas</option>'
    for k in kelas_list:
        selected = " selected" if k == kelas else ""
        pilihan_kelas += f'<option value="{escape(k)}"{selected}>{escape(k)}</option>'

    body = f"""
<div class="card">
<h2>📚 Buku Induk</h2>
<p class="small">
Data Peserta Didik • Umur dihitung otomatis berdasarkan tanggal lahir.
</p>

<form method="get">
<label>Filter Kelas</label>
<select name="kelas" onchange="this.form.submit()">
{pilihan_kelas}
</select>
</form>
</div>

<div class="card">
<div class="table-wrap">
<table style="min-width:900px">
<thead>
<tr>
<th>No</th>
<th>Foto</th>
<th>NIS</th>
<th>Nama</th>
<th>Kelas</th>
<th>Tanggal Lahir</th>
<th>Umur</th>
<th>Aksi</th>
</tr>
</thead>
<tbody>
{rows_html if rows_html else '<tr><td colspan="8" style="text-align:center;padding:25px">Belum ada data siswa.</td></tr>'}
</tbody>
</table>
</div>
</div>
"""

    return page("Buku Induk", body)

