@app.route("/laporan")
@admin_required
def laporan():
    today=date.today()
    period=request.args.get("period","harian")
    dari=request.args.get("dari","").strip()
    sampai=request.args.get("sampai","").strip()

    if dari and sampai:
        try:
            d1=date.fromisoformat(dari)
            d2=date.fromisoformat(sampai)
            if d1>d2:
                d1,d2=d2,d1
        except ValueError:
            d1=d2=today
    elif period=="mingguan":
        d1=today-timedelta(days=6)
        d2=today
    elif period=="bulanan":
        d1=today.replace(day=1)
        d2=today
    else:
        d1=d2=today

    a=d1.strftime("%Y-%m-%d")
    b=d2.strftime("%Y-%m-%d")

    c=None
    try:
        c=db()

        siswa=c._get("absensi", {
            "select":"tanggal,jam,nama,kelas,status",
            "gte.tanggal":a,
            "lte.tanggal":b,
            "order":"tanggal.desc,nama.asc,kelas.asc,jam.asc",
            "limit":"10000"
        })

        tenaga=c._get("absensi_tenaga", {
            "select":"tanggal,jam,nama,jabatan,status",
            "gte.tanggal":a,
            "lte.tanggal":b,
            "order":"tanggal.desc,nama.asc,jam.asc",
            "limit":"10000"
        })

        siswa_kelas=c._get("siswa", {
            "select":"kelas",
            "order":"kelas.asc",
            "limit":"10000"
        })

    except Exception as e:
        if c:
            try:
                c.close()
            except:
                pass
        return page("Laporan Error", f"""<div class="card">
        <h2>❌ Laporan Tidak Dapat Dibuka</h2>
        <div class="warn"><b>Error:</b><br><small>{escape(str(e))}</small></div>
        <a class="btn gray" href="/">Kembali</a>
        </div>"""),500

    finally:
        if c:
            try:
                c.close()
            except:
                pass

    def group(rows,staff=False):
        m={}
        for x in rows:
            tanggal=str(x.get("tanggal") or "")
            nama=str(x.get("nama") or "")
            jabatan=str(x.get("jabatan") or "") if staff else ""
            kelas=str(x.get("kelas") or "") if not staff else ""
            status=str(x.get("status") or "")
            jam=str(x.get("jam") or "-")

            key=(tanggal,nama,jabatan if staff else kelas)

            if key not in m:
                m[key]={
                    "tanggal":tanggal,
                    "nama":nama,
                    "jabatan":jabatan,
                    "kelas":kelas,
                    "masuk":"-",
                    "pulang":"-"
                }

            if status=="Masuk":
                m[key]["masuk"]=jam
            elif status=="Pulang":
                m[key]["pulang"]=jam

        return sorted(
            m.values(),
            key=lambda z:(z["tanggal"],z["nama"]),
            reverse=True
        )

    srrows=group(siswa)
    trrows=group(tenaga,True)

    kelas_count={}
    for x in siswa_kelas:
        k=str(x.get("kelas") or "").strip()
        if k:
            kelas_count[k]=kelas_count.get(k,0)+1

    kelas=[
        {"kelas":k,"total":v}
        for k,v in sorted(kelas_count.items(),key=lambda x:x[0].lower())
    ]

    sr="".join(
        f'<tr><td>{escape(x["tanggal"])}</td><td>{escape(x["nama"])}</td><td>{escape(x["kelas"])}</td><td>{escape(x["masuk"])}</td><td>{escape(x["pulang"])}</td></tr>'
        for x in srrows
    )

    tr="".join(
        f'<tr><td>{escape(x["tanggal"])}</td><td>{escape(x["nama"])}</td><td>{escape(x["jabatan"])}</td><td>{escape(x["masuk"])}</td><td>{escape(x["pulang"])}</td></tr>'
        for x in trrows
    )

    cr="".join(
        f'<tr><td>{escape(x["kelas"])}</td><td>{x["total"]}</td></tr>'
        for x in kelas
    )

    body=f'''<div class="card">
    <h2>📊 Laporan Absensi</h2>
    <a class="btn" href="/laporan?period=harian">Hari Ini</a>
    <a class="btn green" href="/laporan?period=mingguan">7 Hari</a>
    <a class="btn orange" href="/laporan?period=bulanan">Bulan Ini</a>

    <div class="card" style="margin-top:12px;background:#f8fafc">
    <h3>📅 Pilih Periode</h3>
    <form method="get">
    <label>Dari tanggal</label>
    <input type="date" name="dari" value="{a}" required>
    <label>Sampai tanggal</label>
    <input type="date" name="sampai" value="{b}" required>
    <button class="btn purple" type="submit">🔎 Tampilkan Periode</button>
    </form>
    </div>

    <button type="button" class="btn gray" onclick="window.print()">🖨️ PRINT LAPORAN</button>
    <a class="btn green" href="/export_excel?dari={a}&sampai={b}">📥 DOWNLOAD</a>
    <p class="small">Periode: {a} sampai {b}</p>
    </div>

    <div class="card">
    <h3>👨‍🎓 Absensi Siswa</h3>
    <table>
    <tr><th>Tanggal</th><th>Nama</th><th>Kelas</th><th>Jam Masuk</th><th>Jam Pulang</th></tr>
    {sr or '<tr><td colspan="5">Kosong</td></tr>'}
    </table>
    </div>

    <div class="card">
    <h3>👨‍🏫 Absensi Guru/Tendik</h3>
    <table>
    <tr><th>Tanggal</th><th>Nama</th><th>Jabatan</th><th>Jam Masuk</th><th>Jam Pulang</th></tr>
    {tr or '<tr><td colspan="5">Kosong</td></tr>'}
    </table>
    </div>

    <div class="card">
    <h3>📚 Jumlah Siswa per Kelas</h3>
    <table>
    <tr><th>Kelas</th><th>Jumlah</th></tr>
    {cr or '<tr><td colspan="2">Kosong</td></tr>'}
    </table>
    </div>'''

    return page("Laporan",body)


@app.route("/export_excel")
@admin_required
def export_excel():
    period=request.args.get("period",""); today=date.today(); dari=request.args.get("dari","").strip(); sampai=request.args.get("sampai","").strip()
    if dari and sampai:
        try:
            d1=date.fromisoformat(dari); d2=date.fromisoformat(sampai)
            if d1>d2: d1,d2=d2,d1
        except ValueError: d1=d2=today
    elif period=="mingguan": d1=today-timedelta(days=6); d2=today
    elif period=="bulanan": d1=today.replace(day=1); d2=today
    else: d1=d2=today
    a=d1.strftime("%Y-%m-%d"); b=d2.strftime("%Y-%m-%d")
    try:
        from openpyxl import Workbook
        from openpyxl.styles import Font, Alignment
        from openpyxl.drawing.image import Image as XLImage
        from io import BytesIO
        from flask import send_file
    except Exception as e: return f"ERROR DOWNLOAD EXCEL: {type(e).__name__}: {e}",500
    c=db()
    try:
        siswa=c._get("absensi", {
            "select":"tanggal,jam,nama,kelas,status",
            "gte.tanggal":a,
            "lte.tanggal":b,
            "order":"kelas.asc,nama.asc,tanggal.asc,jam.asc",
            "limit":"10000"
        })

        tenaga=c._get("absensi_tenaga", {
            "select":"tanggal,jam,nama,jabatan,status",
            "gte.tanggal":a,
            "lte.tanggal":b,
            "order":"nama.asc,tanggal.asc,jam.asc",
            "limit":"10000"
        })

        kelas_rows=c._get("siswa", {
            "select":"kelas",
            "order":"kelas.asc",
            "limit":"10000"
        })
    finally:
        c.close()
    def group(rows,staff=False):
        m={}
        for x in rows:
            key=(x["tanggal"],x["nama"],x["jabatan"] if staff else x["kelas"])
            if key not in m: m[key]={"tanggal":x["tanggal"],"nama":x["nama"],"jabatan":x["jabatan"] if staff else "","kelas":x["kelas"] if not staff else "","masuk":"-","pulang":"-"}
            if x["status"]=="Masuk": m[key]["masuk"]=x["jam"]
            elif x["status"]=="Pulang": m[key]["pulang"]=x["jam"]
        return sorted(m.values(),key=lambda z:(z["nama"],z["tanggal"]))
    sr=group(siswa); tr=group(tenaga,True); wb=Workbook(); logo_path=os.path.join(os.path.dirname(os.path.abspath(__file__)), "logo_absenku.png")
    try:
        with open(logo_path,"wb") as f: f.write(base64.b64decode(LOGO_B64))
    except Exception:
        logo_path=None
    ws=wb.active; ws.title="Ringkasan";
    if logo_path:
        img=XLImage(logo_path); img.width=75; img.height=75; ws.add_image(img,"G1")
    ws.append([SEKOLAH]); ws.append([f"Laporan Absensi {a} s/d {b}"]); ws.append([]); ws.append(["Tanggal","Nama Siswa","Kelas","Jam Masuk","Jam Pulang"])
    for r in sr: ws.append([r["tanggal"],r["nama"],r["kelas"],r["masuk"],r["pulang"]])
    used={"Ringkasan","Guru-Tendik"}
    for kr in kelas_rows:
        kelas=kr["kelas"]; safe="".join(ch for ch in kelas if ch not in r'[]:*?/\\')[:31] or "Kelas"; base=safe; n=2
        while safe in used: suffix=f"-{n}"; safe=base[:31-len(suffix)]+suffix; n+=1
        used.add(safe); w=wb.create_sheet(safe);
        if logo_path:
            img=XLImage(logo_path); img.width=65; img.height=65; w.add_image(img,"G1")
        w.append([SEKOLAH]); w.append([f"Laporan Absensi Kelas {kelas}",f"{a} s/d {b}"]); w.append([]); w.append(["Tanggal","Nama Siswa","Kelas","Jam Masuk","Jam Pulang"])
        for r in sr:
            if r["kelas"]==kelas: w.append([r["tanggal"],r["nama"],r["kelas"],r["masuk"],r["pulang"]])
    wt=wb.create_sheet("Guru-Tendik");
    if logo_path:
        img=XLImage(logo_path); img.width=65; img.height=65; wt.add_image(img,"G1")
    wt.append([SEKOLAH]); wt.append([f"Laporan Guru/Tendik",f"{a} s/d {b}"]); wt.append([]); wt.append(["Tanggal","Nama","Jabatan","Jam Masuk","Jam Pulang"])
    for r in tr: wt.append([r["tanggal"],r["nama"],r["jabatan"],r["masuk"],r["pulang"]])
    for sh in wb.worksheets:
        sh.row_dimensions[1].height=58
        sh.freeze_panes="A5"
        for cell in sh[1]: cell.font=Font(bold=True,size=14)
        for cell in sh[2]: cell.font=Font(bold=True)
        for cell in sh[4]: cell.font=Font(bold=True)
        for col,width in zip(["A","B","C","D","E"],[14,28,16,14,14]): sh.column_dimensions[col].width=width
        for row in sh.iter_rows():
            for cell in row: cell.alignment=Alignment(vertical="top")
    bio=BytesIO(); wb.save(bio); bio.seek(0); return send_file(bio,as_attachment=True,download_name=f"absenku_{a}_sampai_{b}.xlsx",mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")


@app.errorhandler(Exception)
def handle_server_error(e):
    import traceback
    traceback.print_exc()
    return f"<h1>ERROR SERVER</h1><pre>{escape(traceback.format_exc())}</pre>", 500

