    init_db()
    print(f"{SEKOLAH} - SISTEM ABSENSI BERJALAN")
    print("Buka: http://127.0.0.1:5000")
    app.run(host="127.0.0.1",port=5000,debug=False,threaded=True,use_reloader=False)
